import {targetMatch,wordStatus,goalLabel} from './engine.js';
import {renderGrowth} from './growth.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tones=['terra','sage','blue','lavender','gold','olive','rose'];
const colors=['#ad7b68','#709580','#7796a4','#9586a4','#ad9967','#879678','#ac8ea1'];
export function groupsFor(f,lib){
  if(f.groups?.length)return f.groups.map(g=>({...g,wordIds:g.wordIds.filter(id=>f.wordIds.includes(id))}));
  const children=id=>f.edges.filter(e=>e.from===id).map(e=>e.to),base=Object.hasOwn(lib.words,f.id)&&f.wordIds.includes(f.id)?f.id:null;
  let hubs=children('root:'+f.id).flatMap(id=>id===base&&children(id).length?children(id):[id]);
  const assigned=new Set(base?[base]:[]),groups=[];
  for(const hub of hubs){const ids=[],queue=[hub];while(queue.length){const id=queue.shift();if(assigned.has(id))continue;assigned.add(id);ids.push(id);queue.push(...children(id));}if(ids.length)groups.push({id:hub,label:lib.words[hub]?.meaning.split(/[；，]/)[0]||hub,note:'沿词形联系学习，结合语境确认含义。',wordIds:ids});}
  const rest=f.wordIds.filter(id=>!assigned.has(id));if(rest.length)groups.push({id:'related',label:'其他关联词',note:'同源关系与现代含义分别理解。',wordIds:rest});return groups;
}
export function atlasModel(f,lib,state,{mode='target',branch='',collapsed=new Set(),fontScale=1}={}){
  const requested=new Set(f.wordIds.filter(id=>mode==='full'||targetMatch(lib.words[id],state.settings.goal)||(lib.words[id].studyItemIds||[]).some(x=>targetMatch(lib.studyItems?.[x],state.settings.goal))));
  const raw=groupsFor(f,lib),base=Object.hasOwn(lib.words,f.id)&&f.wordIds.includes(f.id)?f.id:null,seen=new Set(base?[base]:[]);
  const groups=raw.map((g,i)=>{const allIds=g.wordIds.filter(id=>!seen.has(id)&&id!==base);allIds.forEach(id=>seen.add(id));const selected=allIds.filter(id=>requested.has(id));const context=new Set();for(const id of selected){let child=id;const visited=new Set();for(let step=0;step<f.wordIds.length;step++){if(visited.has(child))break;visited.add(child);const edge=f.edges.find(e=>e.to===child);if(!edge||edge.from.startsWith('root:')||edge.from===base)break;if(allIds.includes(edge.from))context.add(edge.from);child=edge.from;}}const ids=allIds.filter(id=>requested.has(id)||context.has(id));return{...g,requested,index:i,tone:tones[i%tones.length],color:colors[i%colors.length],wordIds:ids,context,collapsed:collapsed.has(g.id),h:collapsed.has(g.id)?92:145+Math.ceil(ids.length/2)*96};}).filter(g=>g.wordIds.length);
  let leftY=28,rightY=28;for(const g of groups){const left=leftY<=rightY;g.x=left?28:882;g.y=left?leftY:rightY;g.w=418;if(left)leftY+=g.h+18;else rightY+=g.h+18;}
  const height=Math.max(480,leftY,rightY)+22,root={x:554,y:height/2-98,w:220,h:176};for(const g of groups)for(const k of ['x','y','w','h'])g[k]*=fontScale;for(const k of ['x','y','w','h'])root[k]*=fontScale;return{groups,requested,width:1328*fontScale,height:height*fontScale,root,base,branch:branch||groups[0]?.id,eligibleCount:requested.size};
}
function wordNode(id,g,lib,state,selected,mode){const w=lib.words[id],status=wordStatus(state,lib,id),context=g.context.has(id)&&!g.requested?.has(id),labels={known:'基础已掌握',due:'待复习',review:'复习中',new:'待学',outside:'关联词'};const incoming=lib.families.find(f=>f.id===g.familyId)?.edges.find(e=>e.to===id&&!e.from.startsWith('root:'));const suffix=incoming?.label?.split('：')[0];return`<button class="atlas-word ${status} ${selected===id?'selected':''} ${context?'context':''} ${mode==='review'&&status!=='due'?'background-node':''}" data-word="${esc(id)}" aria-label="${esc(w.word+'，'+w.meaning)}"><strong lang="en">${esc(w.word)}</strong><span class="atlas-word-meaning">${esc(w.pos)} ${esc(w.meaning.split('；')[0])}</span><span class="atlas-word-status">${esc(labels[status])}${suffix?`<i>${esc(suffix)}</i>`:''}</span></button>`;}
function branchHTML(g,f,lib,state,selected,mode){const edges=f.edges.filter(e=>g.wordIds.includes(e.from)&&g.wordIds.includes(e.to));return`<section class="atlas-branch ${g.tone}" data-group="${esc(g.id)}" style="left:${g.x}px;top:${g.y}px;width:${g.w}px;min-height:${g.h}px"><div class="atlas-branch-heading"><span>${String(g.index+1).padStart(2,'0')}</span><h3>${esc(g.label)}</h3><button data-action="atlas-collapse" data-id="${esc(g.id)}" aria-expanded="${!g.collapsed}" aria-label="${g.collapsed?'展开':'收起'} ${esc(g.label)}">${g.collapsed?'+':'−'}</button></div>${g.note?`<p class="atlas-branch-note" title="${esc(g.note)}">${esc(g.note)}</p>`:''}${g.collapsed?`<div class="atlas-collapsed-count">${g.wordIds.length} 个关联词</div>`:`<div class="atlas-words">${g.wordIds.map(id=>wordNode(id,{...g,familyId:f.id},lib,state,selected,mode)).join('')}</div><div class="atlas-relations">${edges.slice(0,3).map(e=>`<span title="${esc(e.label)}"><b>${esc(e.from)}</b> <i>${e.type==='origin'?'同源':'→'}</i> ${esc(e.to)}</span>`).join('')}</div>`}</section>`;}
export function renderAtlas(f,lib,state,options={}){
  if(options.mode==='growth')return renderGrowth(f,lib,state,options);
  const m=atlasModel(f,lib,state,options),mode=options.mode||'target';const lines=m.groups.map(g=>{const left=g.x<500,tx=left?g.x+g.w:g.x,ty=g.y+g.h/2,sx=left?m.root.x:m.root.x+m.root.w,sy=m.root.y+m.root.h/2;return`<path d="M${sx} ${sy} C${left?sx-80:sx+80} ${sy},${left?tx+85:tx-85} ${ty},${tx} ${ty}" stroke="${g.color}" fill="none" stroke-width="1.5" ${f.edges.some(e=>e.type==='origin'&&g.wordIds.includes(e.to)&&e.from.startsWith('root:'))?'stroke-dasharray="7 7"':''}/>`;}).join('');
  const tabs=m.groups.map(g=>`<button class="${m.branch===g.id?'active':''}" data-action="atlas-branch" data-id="${esc(g.id)}">${esc(g.label)}</button>`).join(''),current=m.groups.find(g=>g.id===m.branch)||m.groups[0];
  return`<section class="family-atlas card ${options.mobileFull?'mobile-full':''}"><div class="atlas-toolbar"><div class="atlas-mode-tabs" aria-label="图谱查看方式">${[['target','学习视图'],['full','完整词族'],['growth','逐层展开'],['review','复习视图']].map(([id,label])=>`<button class="${mode===id?'active':''}" data-action="atlas-mode" data-id="${id}">${label}</button>`).join('')}</div><span class="meta">${mode==='full'?f.wordIds.length:m.requested.size} 词 · ${m.groups.length} 分支</span><div class="row"><button class="btn small outline" data-action="atlas-fit">适合屏幕</button><button class="btn small secondary" data-action="export-atlas">导出高清图</button></div></div><div class="atlas-guidance"><span>${mode==='review'?'突出今天到期的词，其他节点作为关联背景。':mode==='full'?'完整词族保留全部关联。':'按 '+esc(goalLabel(state))+' 目标展示，保留必要的关联节点。'}</span><span>点击单词查看卡片</span></div><div class="atlas-desktop"><div class="atlas-scroll" tabindex="0" aria-label="词族总览图，可缩放和移动"><div class="atlas-viewport" style="width:${m.width*(options.zoom||1)}px;height:${m.height*(options.zoom||1)}px"><div class="atlas-stage" style="width:${m.width}px;height:${m.height}px;transform:scale(${options.zoom||1});transform-origin:0 0"><svg class="atlas-lines" width="${m.width}" height="${m.height}" aria-hidden="true">${lines}</svg><div class="atlas-center" style="left:${m.root.x}px;top:${m.root.y}px;width:${m.root.w}px;height:${m.root.h}px"><span>词根 · ROOT</span><button ${m.base?`data-word="${m.base}"`:`data-card="root-${f.id}"`}>${esc(f.label.split('/')[0].trim())}</button>${f.label.includes('/')?`<small>${esc(f.label)}</small>`:''}<p>${esc(f.meaning)}</p><button class="atlas-root-card" data-card="root-${f.id}">词根知识卡</button></div>${m.groups.map(g=>branchHTML(g,f,lib,state,options.selected,mode)).join('')}</div></div></div><div class="atlas-zoom"><button data-action="atlas-zoom-out" aria-label="缩小">−</button><span>${Math.round((options.zoom||1)*100)}%</span><button data-action="atlas-zoom-in" aria-label="放大">＋</button></div></div><div class="atlas-mobile"><div class="atlas-mobile-root"><strong>${esc(f.label)}</strong><span>${esc(f.meaning)}</span><button data-card="root-${f.id}">词根知识卡</button></div><div class="atlas-mobile-tabs">${tabs}</div>${current?`<section class="atlas-mobile-branch ${current.tone}"><h3>${esc(current.label)}</h3><p>${esc(current.note||'')}</p><div class="atlas-words">${current.wordIds.map(id=>wordNode(id,{...current,familyId:f.id},lib,state,options.selected,mode)).join('')}</div><div class="atlas-relations">${f.edges.filter(e=>current.wordIds.includes(e.from)&&current.wordIds.includes(e.to)).map(e=>`<span>${esc(e.from)} <i>${e.type==='origin'?'同源':'→'}</i> ${esc(e.to)} · ${esc(e.label.split('：')[0])}</span>`).join('')}</div></section>`:'<div class="empty"><h3>这个目标下暂没有已核验词条</h3><p>可以切换到完整词族继续探索。</p></div>'}<button class="btn small outline" data-action="atlas-full-mobile">${options.mobileFull?'返回分支视图':'查看完整图'}</button></div><div class="atlas-legend"><span><i></i>构词变化：箭头旁提供词缀线索</span><span><i class="dashed"></i>历史同源：常见义单独理解</span><span>已掌握的词保留关联，跳过学习任务</span></div></section>`;
}
function fitClue(value){let width=0,text='';for(const c of value){width+=/[\u0000-\u007f]/.test(c)?5:10;if(width>178)return text+'…';text+=c;}return text;}
export function atlasSVG(f,lib,state,options={}){
  const m=atlasModel(f,lib,state,{...options,collapsed:new Set()}),head=85,foot=68,H=m.height+head+foot;const x=esc;
  const paths=m.groups.map(g=>{const left=g.x<500,tx=left?g.x+g.w:g.x,ty=g.y+g.h/2+head,sx=left?m.root.x:m.root.x+m.root.w,sy=m.root.y+m.root.h/2+head;return`<path d="M${sx} ${sy} C${left?sx-80:sx+80} ${sy},${left?tx+85:tx-85} ${ty},${tx} ${ty}" stroke="${g.color}" fill="none" stroke-width="2" ${f.edges.some(e=>e.type==='origin'&&g.wordIds.includes(e.to)&&e.from.startsWith('root:'))?'stroke-dasharray="7 7"':''}/>`;}).join('');
  const blocks=m.groups.map(g=>{const content=g.wordIds.map((id,i)=>{const w=lib.words[id],incoming=f.edges.find(e=>e.to===id&&!e.from.startsWith('root:')),clue=incoming?incoming.label+' · '+incoming.from+(incoming.type==='origin'?' 同源 ':' → ')+w.word:'',cx=g.x+18+(i%2)*194,cy=g.y+head+88+Math.floor(i/2)*96;return`<text x="${cx}" y="${cy}" font-size="${w.word.length>18?15:18}" font-weight="700" fill="#263d38">${x(w.word)}</text><text x="${cx}" y="${cy+23}" font-size="13" fill="#64796b">${x(w.pos+' '+w.meaning.split('；')[0].slice(0,17))}</text><text x="${cx}" y="${cy+43}" font-size="10" fill="#819582">${x(fitClue(clue))}</text>`;}).join('');return`<rect x="${g.x}" y="${g.y+head}" width="${g.w}" height="${g.h}" rx="18" fill="#fff" stroke="#dfe6df"/><text x="${g.x+20}" y="${g.y+head+32}" fill="${g.color}" font-size="18" font-weight="700">${String(g.index+1).padStart(2,'0')}  ${x(g.label)}</text><text x="${g.x+20}" y="${g.y+head+56}" fill="#77877b" font-size="12">${x((g.note||'').slice(0,28))}</text>${content}`;}).join('');return`<svg xmlns="http://www.w3.org/2000/svg" width="${m.width}" height="${H}" viewBox="0 0 ${m.width} ${H}"><rect width="100%" height="100%" fill="#f6f7f2"/><g font-family="Microsoft YaHei,Arial,sans-serif"><text x="30" y="42" font-size="29" font-weight="700" fill="#164b3c">${x(f.label)} 词族关系图 · 词根织网</text><text x="30" y="67" font-size="14" fill="#718575">${x(f.meaning)} · ${m.requested.size} 词 · ${x(goalLabel(state))}目标</text>${paths}<rect x="${m.root.x}" y="${m.root.y+head}" width="${m.root.w}" height="${m.root.h}" rx="30" fill="#dce8df"/><text x="${m.root.x+m.root.w/2}" y="${m.root.y+head+73}" text-anchor="middle" font-size="${Math.min(58,Math.floor(185/(f.label.split('/')[0].trim().length*.58)))}" font-weight="700" fill="#164b3c">${x(f.label.split('/')[0].trim())}</text>${f.label.includes('/')?`<text x="${m.root.x+m.root.w/2}" y="${m.root.y+head+107}" text-anchor="middle" font-size="13" fill="#6d8475">${x(f.label)}</text>`:''}<text x="${m.root.x+m.root.w/2}" y="${m.root.y+head+141}" text-anchor="middle" font-size="16" fill="#3d6250">${x(f.meaning)}</text>${blocks}<text x="30" y="${H-29}" font-size="13" fill="#718575">按分支理解关联，用例句巩固词义；历史同源与现代构词分别理解。</text></g></svg>`;
}
